"use strict";(self.webpackChunkwiki_pt_br=self.webpackChunkwiki_pt_br||[]).push([["66491"],{36674(e,a,o){o.r(a),o.d(a,{metadata:()=>i,default:()=>c,frontMatter:()=>r,contentTitle:()=>t,toc:()=>l,assets:()=>d});var i=JSON.parse('{"id":"Sensor/Wio_Terminal/Application/Embedded_ML/Projects_based_Edge_Impulse/pt_Wio-Terminal-TinyML-EI-6","title":"Detec\xe7\xe3o de anomalias para Manuten\xe7\xe3o Preditiva","description":"Detec\xe7\xe3o de anomalias para Manuten\xe7\xe3o Preditiva","source":"@site/docs/Sensor/Wio_Terminal/Application/Embedded_ML/Projects_based_Edge_Impulse/pt_Wio-Terminal-TinyML-EI-6.md","sourceDirName":"Sensor/Wio_Terminal/Application/Embedded_ML/Projects_based_Edge_Impulse","slug":"/Wio-Terminal-TinyML-EI-6","permalink":"/pt-br/Wio-Terminal-TinyML-EI-6","draft":false,"unlisted":false,"editUrl":"https://github.com/Seeed-Studio/wiki-documents/blob/docusaurus-version/sites/pt-BR/docs/Sensor/Wio_Terminal/Application/Embedded_ML/Projects_based_Edge_Impulse/pt_Wio-Terminal-TinyML-EI-6.md","tags":[],"version":"current","lastUpdatedBy":"jianjing Huang","lastUpdatedAt":1675036800000,"frontMatter":{"description":"Detec\xe7\xe3o de anomalias para Manuten\xe7\xe3o Preditiva","title":"Detec\xe7\xe3o de anomalias para Manuten\xe7\xe3o Preditiva","keywords":["Wio_terminal","Embedded_ML","Projects_based_Edge_Impulse"],"image":"https://files.seeedstudio.com/wiki/wiki-platform/S-tempor.png","slug":"/Wio-Terminal-TinyML-EI-6","last_update":{"date":"1/30/2023","author":"jianjing Huang"},"createdAt":"2023-01-31","updatedAt":"2026-03-16","url":"https://wiki.seeedstudio.com/pt-br/Wio-Terminal-TinyML-EI-6/"},"sidebar":"ptBRSidebar","previous":{"title":"Distinguindo Bebidas","permalink":"/pt-br/Wio-Terminal-TinyML-EI-5"},"next":{"title":"Introdu\xe7\xe3o ao TensorFlow Lite Micro","permalink":"/pt-br/Wio-Terminal-TinyML-TFLM-1"}}'),n=o(31085),s=o(71184);let r={description:"Detec\xe7\xe3o de anomalias para Manuten\xe7\xe3o Preditiva",title:"Detec\xe7\xe3o de anomalias para Manuten\xe7\xe3o Preditiva",keywords:["Wio_terminal","Embedded_ML","Projects_based_Edge_Impulse"],image:"https://files.seeedstudio.com/wiki/wiki-platform/S-tempor.png",slug:"/Wio-Terminal-TinyML-EI-6",last_update:{date:"1/30/2023",author:"jianjing Huang"},createdAt:"2023-01-31",updatedAt:"2026-03-16",url:"https://wiki.seeedstudio.com/pt-br/Wio-Terminal-TinyML-EI-6/"},t="Detec\xe7\xe3o de Anomalias com Wio Terminal e Edge Impulse para Manuten\xe7\xe3o Preditiva",d={},l=[{value:"Detec\xe7\xe3o de anomalias e manuten\xe7\xe3o preditiva em poucas palavras",id:"detec\xe7\xe3o-de-anomalias-e-manuten\xe7\xe3o-preditiva-em-poucas-palavras",level:2},{value:"Coletando os dados e treinando o modelo",id:"coletando-os-dados-e-treinando-o-modelo",level:2},{value:"Implanta\xe7\xe3o e teste",id:"implanta\xe7\xe3o-e-teste",level:2},{value:"Utilizando o novo lan\xe7amento da plataforma Blynk IoT",id:"utilizando-o-novo-lan\xe7amento-da-plataforma-blynk-iot",level:2},{value:"Refer\xeancia",id:"refer\xeancia",level:2}];function m(e){let a={a:"a",code:"code",h1:"h1",h2:"h2",header:"header",li:"li",p:"p",pre:"pre",ul:"ul",...(0,s.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(a.header,{children:(0,n.jsx)(a.h1,{id:"detec\xe7\xe3o-de-anomalias-com-wio-terminal-e-edge-impulse-para-manuten\xe7\xe3o-preditiva",children:"Detec\xe7\xe3o de Anomalias com Wio Terminal e Edge Impulse para Manuten\xe7\xe3o Preditiva"})}),"\n",(0,n.jsx)("div",{align:"center",children:(0,n.jsx)("img",{src:"https://files.seeedstudio.com/wiki/Wio-Terminal-TinyML-EI-6/full-Time-0_19_2725-1536x864.png"})}),"\n",(0,n.jsx)(a.p,{children:"Neste projeto, usaremos dados do aceler\xf4metro integrado do Wio Terminal, executaremos detec\xe7\xe3o de anomalias no pr\xf3prio dispositivo e depois enviaremos os dados para a Blynk Edgent Cloud."}),"\n",(0,n.jsx)(a.p,{children:"Anomalias. Ou especificamente detec\xe7\xe3o de anomalias para manuten\xe7\xe3o preditiva. Vamos usar dados do aceler\xf4metro integrado do Wio Terminal, executar a infer\xeancia de um modelo de rede neural e detec\xe7\xe3o de anomalias no dispositivo e depois enviar os dados para a nova vers\xe3o da plataforma Blynk IoT, com uma infinidade de novos recursos, que oferece suporte completo ao Wio Terminal."}),"\n",(0,n.jsx)(a.p,{children:"Para o tutorial completo e demonstra\xe7\xe3o em v\xeddeo, d\xea uma olhada no v\xeddeo a seguir:"}),"\n",(0,n.jsx)("div",{class:"video-container",children:(0,n.jsx)("iframe",{width:"560",height:"315",src:"https://www.youtube.com/embed/gXs-h3eeT1U",frameborder:"0",allow:"accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture",allowfullscreen:!0})}),"\n",(0,n.jsx)(a.p,{children:"Isso foi o QUE, agora quanto ao COMO, vamos come\xe7ar com um exemplo que pode ser mais familiar."}),"\n",(0,n.jsx)(a.h2,{id:"detec\xe7\xe3o-de-anomalias-e-manuten\xe7\xe3o-preditiva-em-poucas-palavras",children:"Detec\xe7\xe3o de anomalias e manuten\xe7\xe3o preditiva em poucas palavras"}),"\n",(0,n.jsx)(a.p,{children:"Se voc\xea treinar um modelo simples de reconhecimento de imagens para reconhecer, digamos, 5 classes diferentes de animais (tigre, elefante, urso, cobra e girafa) e ent\xe3o der a ele a imagem de uma pessoa, ele far\xe1 uma previs\xe3o da melhor forma que conseguir e possivelmente dir\xe1 que \xe9 um elefante. Entra em cena a risada das pessoas comuns, que na verdade n\xe3o entendem muito sobre o funcionamento interno desse modelo espec\xedfico e de vis\xe3o computacional em geral."}),"\n",(0,n.jsx)(a.p,{children:"Claro, o modelo n\xe3o fez nada de errado \u2013 ele processou a imagem, calculou as caracter\xedsticas presentes e ent\xe3o produziu o resultado de classifica\xe7\xe3o com base nessas caracter\xedsticas. Embora, se plotarmos as caracter\xedsticas das classes e as agrupamos, ver\xedamos que, idealmente, as caracter\xedsticas da imagem de um humano est\xe3o longe de qualquer agrupamento de classe e, portanto, representam um \u201Coutlier\u201D."}),"\n",(0,n.jsx)("div",{align:"center",children:(0,n.jsx)("img",{src:"https://files.seeedstudio.com/wiki/Wio-Terminal-TinyML-EI-6/knowing_all_about_outliers_in_machine_learning_sample_points_in_green_are_near_to_each_other.png"})}),"\n",(0,n.jsx)(a.p,{children:"O que, \xe9 claro, poderia ser apenas uma imagem muito estranha de um dos animais, mas na maioria dos casos \xe9 muito mais prov\xe1vel que seja um objeto para o qual o modelo n\xe3o foi treinado para reconhecer."}),"\n",(0,n.jsx)(a.p,{children:"Para tarefas de vis\xe3o computacional e reconhecimento de fala, muitas vezes temos uma classe de \u201Cfundo\u201D para lidar com esse problema, que basicamente representa qualquer coisa que n\xe3o seja as classes de interesse. Em algumas situa\xe7\xf5es, n\xf3s realmente s\xf3 queremos que nosso modelo seja capaz de interpretar todos os dados como \u201Cnormais\u201D e \u201Canormais\u201D. N\xe3o importa quais s\xe3o as caracter\xedsticas exatas de \u201Canormal\u201D \u2013 elas podem ser totalmente diferentes; o importante \xe9 que, se a classe \u201Canormal\u201D for detectada, algumas medidas precisam ser implementadas. O que descrevi agora \xe9 a premissa por tr\xe1s do uso de Machine Learning para manuten\xe7\xe3o preditiva. Monitoramos o estado de um dispositivo, seja um ar-condicionado, bomba d\u2019\xe1gua ou outra m\xe1quina com sensores e, com base no perfil de opera\xe7\xe3o \u201Cnormal\u201D conhecida, tentamos detectar quando algo come\xe7a a dar ERRADO DE LEVE, antes que d\xea ERRADO DE VERDADE."}),"\n",(0,n.jsx)(a.h2,{id:"coletando-os-dados-e-treinando-o-modelo",children:"Coletando os dados e treinando o modelo"}),"\n",(0,n.jsx)(a.p,{children:"Para este projeto, instalei o Wio Terminal em uma bomba d\u2019\xe1gua no p\xe1tio externo do nosso escrit\xf3rio, que tem algumas plantas e peixes."}),"\n",(0,n.jsx)("div",{align:"center",children:(0,n.jsx)("img",{src:"https://files.seeedstudio.com/wiki/Wio-Terminal-TinyML-EI-6/full-Time-0_04_2007-1536x864.png"})}),"\n",(0,n.jsx)(a.p,{children:"Depois coletei duas categorias de amostras \u2013 em repouso e em opera\xe7\xe3o normal \u2013 e treinei um modelo simples para reconhecer essas duas com base na sa\xedda do bloco de processamento Spectral Features."}),"\n",(0,n.jsx)("div",{align:"center",children:(0,n.jsx)("img",{src:"https://files.seeedstudio.com/wiki/Wio-Terminal-TinyML-EI-6/image-1.png"})}),"\n",(0,n.jsx)("div",{align:"center",children:(0,n.jsx)("img",{src:"https://files.seeedstudio.com/wiki/Wio-Terminal-TinyML-EI-6/image-2.png"})}),"\n",(0,n.jsx)(a.p,{children:"Para os par\xe2metros exatos dos blocos de processamento e aprendizado, voc\xea pode dar uma olhada na vers\xe3o p\xfablica do projeto que compartilhei. O \xfanico ajuste significativo que fiz foi mudar o filtro de low para high, o que tornou as caracter\xedsticas das diferentes classes mais proeminentes. Distinguir entre repouso e opera\xe7\xe3o normal da bomba, \xe9 claro, acabou sendo realmente f\xe1cil. A tarefa mais desafiadora foi a detec\xe7\xe3o de mau funcionamento. Para simular um mau funcionamento, eu tirava a bomba d\u2019\xe1gua do tanque \u2013 isso basicamente fazia os n\xedveis de som e vibra\xe7\xe3o diminu\xedrem."}),"\n",(0,n.jsx)("div",{align:"center",children:(0,n.jsx)("img",{src:"https://files.seeedstudio.com/wiki/Wio-Terminal-TinyML-EI-6/full-Time-0_19_2725-1536x864.png"})}),"\n",(0,n.jsx)(a.p,{children:"Observando a amostra de mau funcionamento, no explorador de caracter\xedsticas nos eixos accX RMS, accY RMS e accZ RMS, vemos que ela fica na metade do caminho entre as amostras de repouso e de opera\xe7\xe3o normal."}),"\n",(0,n.jsx)("div",{align:"center",children:(0,n.jsx)("img",{src:"https://files.seeedstudio.com/wiki/Wio-Terminal-TinyML-EI-6/image-3-1536x906.png"})}),"\n",(0,n.jsx)(a.p,{children:"Podemos usar isso a nosso favor treinando uma nova (segunda) rede que cria agrupamentos em torno dos dados que j\xe1 vimos e compara os dados recebidos com esses agrupamentos. Se a dist\xe2ncia at\xe9 um agrupamento for muito grande, a amostra \xe9 sinalizada como uma anomalia."}),"\n",(0,n.jsx)(a.p,{children:"Ap\xf3s tentativa e erro, descobri que uma contagem de clusters bem baixa e um limiar de dist\xe2ncia de 0.5 funcionam melhor para detec\xe7\xe3o de anomalias, mas isso \xe9 muito espec\xedfico de cada caso e depende dos seus dados. Uma coisa que ajudou a aumentar a precis\xe3o foi fixar o Wio Terminal firmemente na bomba d\u2019\xe1gua com cola \u2013 para um dispositivo real voc\xea pode usar parafusos. Antes de fix\xe1-lo firmemente, o Wio Terminal balan\xe7ava aleatoriamente, o que introduzia muito ru\xeddo nas amostras de opera\xe7\xe3o normal."}),"\n",(0,n.jsx)(a.h2,{id:"implanta\xe7\xe3o-e-teste",children:"Implanta\xe7\xe3o e teste"}),"\n",(0,n.jsx)(a.p,{children:"Depois que o modelo \xe9 treinado e testado usando o modo Live classification, \xe9 hora de implant\xe1-lo de volta no dispositivo. Compilamos e baixamos a biblioteca Arduino, extra\xedmos para a pasta de bibliotecas do Arduino e ent\xe3o modificamos o sketch nano33_ble_sense_accelerometer para corresponder ao aceler\xf4metro que temos no Wio Terminal. Para um teste simples usamos a tela LCD, que acende em vermelho se uma anomalia for detectada."}),"\n",(0,n.jsx)(a.pre,{children:(0,n.jsx)(a.code,{className:"language-cpp",children:'#define ANOMALY_THRESHOLD 0.5\n\n/* Includes ---------------------------------------------------------------- */\n#include <wio_anomaly_detection_inference.h>\n#include"LIS3DHTR.h"\n#include"TFT_eSPI.h"\n\nTFT_eSPI tft;\nLIS3DHTR<TwoWire> lis;\n\n/* Constant defines -------------------------------------------------------- */\n#define CONVERT_G_TO_MS2    9.80665f\n\n/* Private variables ------------------------------------------------------- */\nstatic bool debug_nn = false; // Set this to true to see e.g. features generated from the raw signal\n\n/**\n* @brief      Arduino setup function\n*/\nvoid setup()\n{\n    // put your setup code here, to run once:\n    Serial.begin(115200);\n    //while (!Serial) {delay(10);}\n\n    Serial.println("Edge Impulse Inferencing Demo");\n\n    tft.begin();\n    tft.setRotation(3);\n\n    lis.begin(Wire1);\n\n    if (!lis.available()) {\n    Serial.println("Failed to initialize IMU!");\n    while (1);\n    }\n    else {\n        ei_printf("IMU initialized\\r\\n");\n    }\n    lis.setOutputDataRate(LIS3DHTR_DATARATE_100HZ); // Setting output data rage to 25Hz, can be set up tp 5kHz \n    lis.setFullScaleRange(LIS3DHTR_RANGE_16G); // Setting scale range to 2g, select from 2,4,8,16g\n\n\n    if (EI_CLASSIFIER_RAW_SAMPLES_PER_FRAME != 3) {\n        ei_printf("ERR: EI_CLASSIFIER_RAW_SAMPLES_PER_FRAME should be equal to 3 (the 3 sensor axes)\\n");\n        return;\n    }\n}\n\n/**\n* @brief      Printf function uses vsnprintf and output using Arduino Serial\n*\n* @param[in]  format     Variable argument list\n*/\nvoid ei_printf(const char *format, ...) {\n   static char print_buf[1024] = { 0 };\n\n   va_list args;\n   va_start(args, format);\n   int r = vsnprintf(print_buf, sizeof(print_buf), format, args);\n   va_end(args);\n\n   if (r > 0) {\n       Serial.write(print_buf);\n   }\n}\n\n/**\n* @brief      Get data and run inferencing\n*\n* @param[in]  debug  Get debug info if true\n*/\nvoid loop()\n{\n\n    ei_printf("Sampling...\\n");\n\n    // Allocate a buffer here for the values we\'ll read from the IMU\n    float buffer[EI_CLASSIFIER_DSP_INPUT_FRAME_SIZE] = { 0 };\n\n    for (size_t ix = 0; ix < EI_CLASSIFIER_DSP_INPUT_FRAME_SIZE; ix += 3) {\n        // Determine the next tick (and then sleep later)\n        uint64_t next_tick = micros() + (EI_CLASSIFIER_INTERVAL_MS * 1000);\n\n        lis.getAcceleration(&buffer[ix], &buffer[ix+1], &buffer[ix + 2]);\n        buffer[ix + 0] *= CONVERT_G_TO_MS2;\n        buffer[ix + 1] *= CONVERT_G_TO_MS2;\n        buffer[ix + 2] *= CONVERT_G_TO_MS2;\n\n        delayMicroseconds(next_tick - micros());\n    }\n\n    // Turn the raw buffer in a signal which we can the classify\n    signal_t signal;\n    int err = numpy::signal_from_buffer(buffer, EI_CLASSIFIER_DSP_INPUT_FRAME_SIZE, &signal);\n    if (err != 0) {\n        ei_printf("Failed to create signal from buffer (%d)\\n", err);\n        return;\n    }\n\n    // Run the classifier\n    ei_impulse_result_t result = { 0 };\n\n    err = run_classifier(&signal, &result, debug_nn);\n    if (err != EI_IMPULSE_OK) {\n        ei_printf("ERR: Failed to run classifier (%d)\\n", err);\n        return;\n    }\n\n    // print the predictions\n    ei_printf("Predictions ");\n    ei_printf("(DSP: %d ms., Classification: %d ms., Anomaly: %d ms.)",\n        result.timing.dsp, result.timing.classification, result.timing.anomaly);\n    ei_printf(": \\n");\n    for (size_t ix = 0; ix < EI_CLASSIFIER_LABEL_COUNT; ix++) {\n        ei_printf("    %s: %.5f\\n", result.classification[ix].label, result.classification[ix].value);\n    }\n#if EI_CLASSIFIER_HAS_ANOMALY == 1\n    ei_printf("    anomaly score: %.3f\\n", result.anomaly);\n\n  if (result.anomaly > ANOMALY_THRESHOLD)\n  {       \n    tft.fillScreen(TFT_RED);\n    tft.setFreeFont(&FreeSansBoldOblique12pt7b);\n    tft.drawString("Anomaly detected", 20, 80);\n    delay(1000);\n    tft.fillScreen(TFT_WHITE);\n  }\n\n#endif\n}\n\n#if !defined(EI_CLASSIFIER_SENSOR) || EI_CLASSIFIER_SENSOR != EI_CLASSIFIER_SENSOR_ACCELEROMETER\n#error "Invalid model for current sensor"\n#endif\n'})}),"\n",(0,n.jsx)(a.p,{children:"Claro que, para uma aplica\xe7\xe3o real, esse tipo de notifica\xe7\xe3o provavelmente n\xe3o vai funcionar, porque n\xe3o h\xe1 uma pessoa monitorando isso constantemente."}),"\n",(0,n.jsx)(a.h2,{id:"utilizando-o-novo-lan\xe7amento-da-plataforma-blynk-iot",children:"Utilizando o novo lan\xe7amento da plataforma Blynk IoT"}),"\n",(0,n.jsx)(a.p,{children:"Para tornar este demo \xfatil, vamos usar a plataforma Blynk IoT."}),"\n",(0,n.jsx)("div",{align:"center",children:(0,n.jsx)("img",{src:"https://files.seeedstudio.com/wiki/Wio-Terminal-TinyML-EI-6/b641e2030c1c47fbc7161c98a7e5d998.jpg"})}),"\n",(0,n.jsx)(a.p,{children:"A plataforma Blynk IoT inclui recursos como um painel web para monitorar dispositivos, gerenciar quem acessa os dados, um gerenciador de WI-FI para um procedimento de configura\xe7\xe3o simples, uma nova abordagem para cria\xe7\xe3o de modelo de dispositivo, entre outros."}),"\n",(0,n.jsx)(a.p,{children:"V\xe1 para blynk.cloud, registre uma conta ou crie uma nova. Em seguida, crie um novo template \u2013 templates s\xe3o modelos digitais do dispositivo que podem ser herdados por m\xfaltiplos dispositivos com funcionalidade semelhante. O poder dos templates est\xe1 na atualiza\xe7\xe3o instant\xe2nea do modelo de dados do dispositivo, independentemente do tamanho da sua frota de dispositivos."}),"\n",(0,n.jsx)(a.p,{children:"Escolha Arduino Uno como hardware e Wi-Fi como tipo de conex\xe3o. Depois preencha as abas Datastreams e Dashboard como nos screenshots a seguir e salve as altera\xe7\xf5es."}),"\n",(0,n.jsx)("div",{align:"center",children:(0,n.jsx)("img",{src:"https://files.seeedstudio.com/wiki/Wio-Terminal-TinyML-EI-6/image-4-1536x551.png"})}),"\n",(0,n.jsx)("div",{align:"center",children:(0,n.jsx)("img",{src:"https://files.seeedstudio.com/wiki/Wio-Terminal-TinyML-EI-6/image-5.png"})}),"\n",(0,n.jsx)(a.p,{children:"N\xe3o estamos usando as abas Metadata ou Events neste projeto. A finalidade principal dos componentes principais do template de dispositivo:"}),"\n",(0,n.jsxs)(a.ul,{children:["\n",(0,n.jsx)(a.li,{children:"Metadata \u2013 dados adicionais sobre o dispositivo que voc\xea pode configurar."}),"\n",(0,n.jsx)(a.li,{children:"Datastreams \u2013 uma entidade para definir os dados que entram e saem do dispositivo. No geral, \xe9 muito semelhante a Virtual Pins (que tamb\xe9m podem ser usados)."}),"\n",(0,n.jsx)(a.li,{children:"Events \u2013 uma lista de alertas e notifica\xe7\xf5es importantes."}),"\n",(0,n.jsx)(a.li,{children:"Web Dashboard \u2013 Um conjunto de Widgets no aplicativo Web"}),"\n",(0,n.jsx)(a.li,{children:"Mobile Dashboard \u2013 Um conjunto de Widgets no aplicativo Mobile"}),"\n"]}),"\n",(0,n.jsx)(a.p,{children:"Crie um novo dispositivo na aba My Devices \u2013 escolha o template que voc\xea criou e d\xea a ele um nome \xfanico."}),"\n",(0,n.jsx)(a.p,{children:"Agora a interface web est\xe1 pronta para receber os dados do nosso dispositivo. Baixe o sketch de exemplo do reposit\xf3rio de sketches de exemplo do Seeed Wio Terminal \u2013 al\xe9m do arquivo principal do sketch ele tamb\xe9m cont\xe9m arquivos auxiliares, onde o c\xf3digo do gerenciador de Wi-Fi est\xe1 localizado. No arquivo principal do sketch, o c\xf3digo de coleta de dados/processamento de dados/infer\xeancia que usamos para testar com a tela LCD foi movido para a fun\xe7\xe3o run_inference(). O ID da classe com maior confian\xe7a (se a confian\xe7a estiver acima do limite definido) \xe9 salvo dentro da vari\xe1vel global best_result e, juntamente com os dados dos sensores de luz e som, est\xe1 sendo enviado para o servidor Blynk em intervalos peri\xf3dicos. Lembre-se de alterar BLYNK_TEMPLATE_ID e BLYNK_DEVICE_NAME para aqueles do seu template de Dispositivo."}),"\n",(0,n.jsx)("div",{align:"center",children:(0,n.jsx)("img",{src:"https://files.seeedstudio.com/wiki/Wio-Terminal-TinyML-EI-6/image-6.png"})}),"\n",(0,n.jsx)(a.p,{children:"Depois que voc\xea carregar o c\xf3digo no Wio Terminal, ele criar\xe1 um hotspot, ao qual voc\xea poder\xe1 se conectar com seu telefone. Ao se conectar, voc\xea ser\xe1 automaticamente redirecionado para uma p\xe1gina simples de configura\xe7\xe3o, onde precisa inserir as credenciais do seu WiFi, seu token de API (voc\xea pode encontr\xe1-lo clicando no seu dispositivo na aba My Devices e depois indo em Device Info) e ent\xe3o clicar em Connect. Em seguida, o Wio Terminal se conectar\xe1 \xe0 rede WiFi e ao servidor em nuvem Blynk e come\xe7ar\xe1 a enviar os dados. Voc\xea pode pressionar o dispositivo na aba My Devices e ver os belos gr\xe1ficos e a mensagem de status. Voc\xea pode ver os resultados do teste no final do v\xeddeo."}),"\n",(0,n.jsx)(a.p,{children:"Obviamente, a mesma abordagem pode ser aplicada \xe0 detec\xe7\xe3o de irregularidades na opera\xe7\xe3o de outras m\xe1quinas \u2013 podemos usar o aceler\xf4metro para praticamente tudo que tenha partes m\xf3veis, j\xe1 que estas produzem vibra\xe7\xe3o que podemos medir. Se o dispositivo emitir sons aud\xedveis, tamb\xe9m podemos usar um microfone. Uma combina\xe7\xe3o de sensores pode funcionar ainda melhor. H\xe1 outras boas aplica\xe7\xf5es onde a manuten\xe7\xe3o preditiva pode ser usada? Escreva suas ideias nos coment\xe1rios! Espero que este artigo e v\xeddeo tenham sido \xfateis para voc\xea!"}),"\n",(0,n.jsx)(a.h2,{id:"refer\xeancia",children:"Refer\xeancia"}),"\n",(0,n.jsxs)(a.ul,{children:["\n",(0,n.jsxs)(a.li,{children:["\n",(0,n.jsx)(a.p,{children:(0,n.jsx)(a.a,{href:"https://studio.edgeimpulse.com/public/31205/latest",children:"Projeto p\xfablico do Edge Impulse"})}),"\n"]}),"\n",(0,n.jsxs)(a.li,{children:["\n",(0,n.jsx)(a.p,{children:(0,n.jsx)(a.a,{href:"https://github.com/Seeed-Studio/Seeed_Arduino_Sketchbook/tree/master/examples/WioTerminal_TinyML_5_Anomaly_Detection",children:"Projeto Github"})}),"\n"]}),"\n"]})]})}function c(e={}){let{wrapper:a}={...(0,s.R)(),...e.components};return a?(0,n.jsx)(a,{...e,children:(0,n.jsx)(m,{...e})}):m(e)}},71184(e,a,o){o.d(a,{R:()=>r,x:()=>t});var i=o(14041);let n={},s=i.createContext(n);function r(e){let a=i.useContext(s);return i.useMemo(function(){return"function"==typeof e?e(a):{...a,...e}},[a,e])}function t(e){let a;return a=e.disableParentContext?"function"==typeof e.components?e.components(n):e.components||n:r(e.components),i.createElement(s.Provider,{value:a},e.children)}}}]);